SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, CORR(temp_c, pressure) OVER (PARTITION BY device_code) AS corr_temp_c_pressure, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits ASC, id ASC) AS row_seq, NTILE(10) OVER (PARTITION BY device_code ORDER BY temp_c ASC, id ASC) AS temp_c_bucket, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY status_bits ASC, id ASC) AS seq_no FROM device_readings;
